def repair_duplicates(apps, schema_editor):
    """Students with more than one ACTIVE teacher (the admin «ربط بمعلم» used to add one without ending the other):
    keep the most recent assignment active and END the others (never delete: active=False, ended_at, end_reason
    `repair_duplicate`), each recorded in the audit log with both teachers. Learning records are untouched."""
    from django.db.models import Count
    from django.utils import timezone

    TA = apps.get_model("accounts", "TeacherAssignment")
    AuditEvent = apps.get_model("core", "AuditEvent")
    now = timezone.now()
    dup = TA.objects.filter(active=True).values("student_id").annotate(n=Count("id")).filter(n__gt=1).values_list("student_id", flat=True)
    for sid in list(dup):
        rows = list(TA.objects.filter(student_id=sid, active=True).order_by("-created_at", "-pk"))
        keep, ended = rows[0], rows[1:]
        for a in ended:
            TA.objects.filter(pk=a.pk).update(active=False, ended_at=now, end_reason="repair_duplicate")
            AuditEvent.objects.create(action="data.teacher_assignment_repaired", target_type="accounts.teacherassignment", target_id=str(a.pk),
                                      data={"student": sid, "ended_teacher": a.teacher_id, "kept_teacher": keep.teacher_id,
                                            "kept_assignment": keep.pk})


